import { ObservedIssue } from 'app/features/observe/observed-issue/model/observed-issue.model';
import { ObservedIssueRepository } from 'app/features/observe/observed-issue/repository/observed-issue-repository.service';
import { ConfirmAction } from 'app/shared/toolkit/action/confirm-action';
import { Component, inject } from '@angular/core';

@Component({ selector: 'observed-issue-view-ignore-action', standalone: false, template: '' })
export class ObservedIssueViewIgnoreActionComponent extends ConfirmAction<ObservedIssue> {
  readonly name = 'ignore';
  protected readonly scope = 'observe/observed-issue';
  protected readonly repository = inject(ObservedIssueRepository);

  protected override appliesTo(items: ObservedIssue[]) {
    return (
      items.every((item) => item.status !== 'ignored') &&
      items.every((item) => (item.status?.toLowerCase() ?? null) !== 'ignored') &&
      true
    );
  }
  protected execute([item]: ObservedIssue[]) {
    return this.repository.ignore(item.uid);
  }
}
